def plan(id,label,agents,risk,meds,extra,page,note=None):
 d=dict(id=id,label=label,active_medicines=agents,emetogenic_risk=risk,medicines=copy.deepcopy(meds),additional_support=extra,source_page=page,source_checked=DATE)
 if note:d['prescription_note']=note
